import XCTest
@testable import LookoutCore
final class CoreTests:XCTestCase {
    func testAddresses()throws{XCTAssertEqual(try AddressResolver.resolve("example.com/a")?.absoluteString,"https://example.com/a");XCTAssertEqual(try AddressResolver.resolve("localhost:4397/a")?.scheme,"http");XCTAssertNil(try AddressResolver.resolve("lookout:home"))}
    func testUnsafeSchemes(){for value in ["javascript:alert(1)","file:///etc/passwd","data:text/html,test","https://user:pass@example.com"]{XCTAssertThrowsError(try AddressResolver.resolve(value))}}
    func testSearchEncoding()throws{let url=try XCTUnwrap(AddressResolver.resolve("cats & dogs",provider:.duckduckgo));XCTAssertEqual(URLComponents(url:url,resolvingAgainstBaseURL:false)?.queryItems?.first?.value,"cats & dogs")}
    func testTokenURLsNotPersisted(){XCTAssertNil(AddressResolver.persisted(URL(string:"https://a.com/callback?code=secret")));XCTAssertNil(AddressResolver.persisted(URL(string:"https://a.com/#access_token=secret")));XCTAssertEqual(AddressResolver.persisted(URL(string:"https://a.com/page#section")),"https://a.com/page")}
    func testPrivateHistoryExcluded(){var archive=Archive();archive.addVisit(URL(string:"https://example.com")!,title:"Private",privateMode:true);XCTAssertTrue(archive.history.isEmpty)}
    func testVisitDeduplication(){var archive=Archive();for _ in 0..<3{archive.addVisit(URL(string:"https://example.com")!,title:"Example",privateMode:false)};XCTAssertEqual(archive.history.count,1)}
    func testRemoveSpaceKeepsPages(){var window=WindowRecord.fresh();let second=SpaceRecord(name:"Work");window.spaces.append(second);window.tabs.append(TabRecord(spaceID:second.id,address:"https://example.com"));window.removeSpace(second.id);XCTAssertEqual(window.spaces.count,1);XCTAssertEqual(window.tabs.count,2);XCTAssertTrue(window.tabs.allSatisfy{$0.spaceID==window.spaces[0].id})}
    func testRepairInvalidSelection(){var window=WindowRecord.fresh();window.selectedID=UUID();window.validate();XCTAssertEqual(window.selectedID,window.tabs[0].id)}
    func testSessionRoundTrip()throws{let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);defer{try? FileManager.default.removeItem(at:root)};let file=SessionFile(url:root.appendingPathComponent("session.json"));var archive=Archive(windows:[.fresh()]);archive.trails=[TrailRecord(name:"Research",purpose:"Explore",tabs:[TabRecord(spaceID:UUID(),title:"Page",address:"https://example.com")])];try file.save(archive);let restored=try file.load();XCTAssertEqual(restored.windows,archive.windows);XCTAssertEqual(restored.trails,archive.trails)}
    func testDamagedSessionPreserved()throws{let url=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);defer{try? FileManager.default.removeItem(at:url)};let original=Data("broken".utf8);try original.write(to:url);XCTAssertThrowsError(try SessionFile(url:url).load());XCTAssertEqual(try Data(contentsOf:url),original)}
    func testFutureVersionRefused()throws{var archive=Archive();archive.schemaVersion=2;XCTAssertThrowsError(try archive.validate())}
    func testTrailExcludesUnsafeSources(){let trail=TrailRecord(name:"Read",purpose:"Think",tabs:[TabRecord(spaceID:UUID(),title:"Good",address:"https://example.com"),TabRecord(spaceID:UUID(),title:"Bad",address:"javascript:alert(1)"),TabRecord(spaceID:UUID(),title:"Token",address:"https://a.com/?token=secret")]);XCTAssertEqual(trail.pages.count,1);XCTAssertTrue(trail.markdown.contains("## Sources"));XCTAssertTrue(trail.markdown.contains("Think"));XCTAssertFalse(trail.markdown.contains("secret"))}
    func testTrailBranchesAndSpaceIsolation(){let space=UUID();let root=TabRecord(spaceID:space);let child=TabRecord(spaceID:space,parentID:root.id);let cousin=TabRecord(spaceID:space,parentID:root.id);let unrelated=TabRecord(spaceID:space);let otherSpace=TabRecord(spaceID:UUID(),parentID:root.id);let result=TrailGraph.branch(selected:child.id,tabs:[root,child,cousin,unrelated,otherSpace]);XCTAssertEqual(result,Set([root.id,child.id,cousin.id]))}
    func testTrailCycleTerminates(){let space=UUID();var a=TabRecord(spaceID:space);let b=TabRecord(spaceID:space,parentID:a.id);a.parentID=b.id;XCTAssertEqual(TrailGraph.branch(selected:a.id,tabs:[a,b]),Set([a.id,b.id]))}
}
